#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so the GC can't collect it mid-game (crash in packaged build:
	// AddPoints on a dangling pointer after garbage collection).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "ScoreTracker was a plain C++ pointer (UArenaScoreTracker*) without UPROPERTY() in ArenaGameMode.h, so the garbage collector could collect the object it pointed to during play (log: 'LogGarbage: Collecting garbage: 412 objects purged'). The dangling pointer was then dereferenced in UArenaScoreTracker::AddPoints() called from AArenaGameMode::OnGoalScored(), causing EXCEPTION_ACCESS_VIOLATION. Fixed by making ScoreTracker a UPROPERTY() TObjectPtr<UArenaScoreTracker>.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary was not cooked into the packaged build (log: \"LogStreaming: Error: Couldn't find file for package /Game/Data/Palettes/DA_Primary\"). LoadObject returned null and the HUD fell back to gray. DefaultGame.ini only always-cooked /Game/Data/Effects, not /Game/Data/Palettes. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to DefaultGame.ini."
}
